import * as React from "react";

export type GamepadWirelessIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function GamepadWirelessIcon({ size = 20, ...props }: GamepadWirelessIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4.5" y="10" width="15" height="8" rx="4" /><path d="M9.5 5.5a5 5 0 0 1 5 0M10 13v3M8.5 14.5h3" />
    </svg>
  );
}
